<template>
    
	<Layout >
		
        <div class="container box_general" >
            <div class="header_box">
                <h2><i class="pe-7s-date"></i>Pacientes</h2>
            </div>

            <div class="filters-box" >
					<div class="filter">
						<label>BUSCAR</label>
						<div class="filter-input">
							<i class="icon icon-search"></i>
							<input 
								type="text" 
								class="form-control" 
								placeholder="Buscar" 
								v-model="filters.search" 
								@keyup.enter="updateFilters($event)">
							<div class="btn btn-light btn-clear-filter" v-if="filters.search" @click="filters.search=null; updateFilters()"><i class="icon icon-close"></i></div>
						</div>
					</div>
					
				</div>

				<table class="table table-clickeable">
					<tr class="table-head">
						<td>Nombre</td>
						<td>Contacto</td>
						<td>Dirección</td>
					</tr>
					
					<router-link tag="tr" :to="`${$route.path}/${item.id}`" v-for="item of list" :key="item.id" >
						<td>{{item.name}} {{item.lastname}}</td>
						<td>
							<div class="tc">
								<span >{{item.email}}</span>
								<span class="text-primary" v-if="item.phone && item.phone.validated">{{item.phone.international}}</span>
							</div>
						</td>
						<td>
							<div class="tc" v-if="item.address">
								<span >{{item.address.city}}</span>
								<span class="text-secondary" v-if="item.address.country && item.address.country.name">{{item.address.country.name}}</span>
							</div>
						</td>
					</router-link>
					
				</table>


				<div class="alert alert-info text-center" v-if="list.length==0" >No se han encontrado pacientes</div>
				
				<Pagination :pageData="pagination" @pageChange="pageChange" />

            
        </div>
            
    </Layout>
</template>

<script>
import gql from 'graphql-tag'

export default {
    name: 'Bookings',
    
    metaInfo: {
		title: 'Reservas',
	},
    
    data() {
        return {
            list:[],
            loading:true,
            
			pagination:{
				length:20
			},
            paginatorInfo:null,
            initDateRange:{ 
                startDate:null,
                endDate: null,
            },
        }
    },
    beforeMount(){
		this.filters = this.getValidUrlParams();
		this.load();
	},
    
    methods:{
        
        load(){
			this.loading = true;
			this.$apollo.query({
				query: gql`query ($take: Int, $skip: Int, $search: String) {
					patients(take: $take, skip: $skip, search: $search) {
						data{
							id
							name
							lastname
							email
							phone{
								countryCode
								national
								international
								type
								validated
							}
						}
						pageInfo{
							totalItems
						}
					}
				}`,
				variables: {
					take: this.pagination.length,
					skip: this.pagination.skip,
					search: this.filters.search,
				},
				fetchPolicy: 'no-cache',
			})
			.then((data) => {
				this.list = data.data.patient.data.map((item)=>{
					return { ...item, loading:false}
				})
				this.pagination.pageInfo = data.data.patient.pageInfo
				this.loading = false
			})
        },
        
    },
    
    
}
</script>

